  ('zcrm_5797994000002316697', 'NXT Power', 'NXT Power', 'Ari Gerard', 'CEO', 'NXT Power helps businesses in a diverse range of industries take on their toughest power quality challenges with unparalleled experience and expertise. Here are just a few markets we work with regularly.', 'HV STEM', 'Manufacturing Technology', 'Spring 2025', NULL, 'Reached Out', 'Ari Gerard', 'Rejected', NULL, NULL, NULL, '2025-02-24 11:43:40', '2025-08-26 07:44:23', '2025-08-26 07:44:23'),
