  ('zcrm_5797994000002382252', 'Sotira', 'Sotira', 'Jordan Marquez', 'Amrita Bhasin', 'Sotira is a B2B SaaS startup and integrated marketplace that uses artificial intelligence to bundle and match surplus inventory suppliers to buyers. Sotira enables suppliers to get a return on their surplus inventory and cash upfront and saves buyers time and labor in sourcing, negotiating and purchasing top quality goods', 'HV STEM', 'SaaS', 'Spring 2025', NULL, 'Reached Out', 'Jordan Marquez', 'Rejected', NULL, NULL, NULL, '2025-03-05 07:35:45', '2025-05-08 10:02:17', '2025-05-08 10:02:17'),
  ('zcrm_5797994000002382278', 'DryMerge', 'DryMerge', 'Jordan Marquez', 'Edward Frazer', 'DryMerge is a chatbot that facilitates the development of custom processes and API integrations for teams and SaaS customers. The Drymerge chatbot communicates with clients or colleagues directly, takes note of their needs, and promptly builds workflows and API connections on top of your product to satisfy them.', 'HV STEM', 'SaaS', 'Spring 2025', NULL, 'Reached Out', 'Jordan Marquez', 'Rejected', NULL, NULL, NULL, '2025-03-05 07:36:46', '2025-05-08 10:02:11', '2025-05-08 10:02:11'),
  ('zcrm_5797994000002382304', 'Cimba AI', 'Cimba AI', 'Jordan Marquez', 'Subrata B', 'Cimba.AI, the Gen-AI-native platform that gives enterprises the power to create custom adaptive AI agents that can produce deep insights and recommend and trigger business actions based on internal data and knowledge base. The platform leverages self-training artificial intelligence that learns and adapts to an organization’s unique knowledgebase', 'HV STEM', 'SaaS', 'Spring 2025', NULL, 'Reached Out', 'Jordan Marquez', 'Rejected', NULL, NULL, NULL, '2025-03-05 07:37:54', '2025-05-08 10:02:08', '2025-05-08 10:02:08'),
  ('zcrm_5797994000002382330', 'Plot', 'Plot', 'Jordan Marquez', 'Phuoc Phan', 'Plot is an end-to-end creative operations platform for teams to manage projects, integrate with creative tools, and collaborate with distributed teams (i.e. agencies, clients, content creators, freelancers). Quickly check project progress, access deliverables, provide feedback and approve — all in one. Plot is headquartered in New York City, United', 'HV STEM', 'SaaS', 'Spring 2025', NULL, 'Reached Out', 'Jordan Marquez', 'Rejected', NULL, NULL, NULL, '2025-03-05 07:39:01', '2025-05-08 10:02:04', '2025-05-08 10:02:04'),
  ('zcrm_5797994000002382356', 'Ribbon', 'Ribbon', 'Jordan Marquez', 'Ashesh Jani', 'Ribbon is the estate center for financial institutions that allows them to capture the next generation of customers. Ribbon finds an inheritance you may not even know you had and has real people to help you in case you have questions. It was founded in 2023 and is located in San Francisco, California. / Pre-seed /', 'HV STEM', 'SaaS', 'Spring 2025', NULL, 'Reached Out', 'Jordan Marquez', 'Rejected', NULL, NULL, NULL, '2025-03-05 07:40:09', '2025-05-08 10:01:59', '2025-05-08 10:01:59'),
  ('zcrm_5797994000002382382', 'MiddleWareHQ', 'MiddleWareHQ', 'Jordan Marquez', 'Dhruv Agarwal', 'Middleware is a B2B SaaS platform for engineering leadership to make it more productive. Its platform frees up time-consuming and repetitive follow-ups to ensure smooth product delivery and helps to identify workflow bottlenecks easily./ Seed', 'HV STEM', 'SaaS', 'Spring 2025', NULL, 'Reached Out', 'Jordan Marquez', 'Rejected', NULL, NULL, NULL, '2025-03-05 07:41:20', '2025-05-08 10:01:54', '2025-05-08 10:01:54'),
  ('zcrm_5797994000002382408', 'DexyAI', 'DexyAI', 'Jordan Marquez', 'Utsav Singla', 'Dexy AI is an autonomous AI SDR that handles prospecting, outreach, conversations, and booking meetings via email and LinkedIn. With the ability to process trillions of data points and operate 24/7, Dexy scales your outbound prospecting without breaks or limits. It engages with every prospect fitting your ideal customer profile, infinitely / Pre-Seed', 'HV STEM', 'SaaS', 'Spring 2025', NULL, 'Reached Out', 'Jordan Marquez', 'Rejected', NULL, NULL, NULL, '2025-03-05 07:42:28', '2025-05-08 10:01:50', '2025-05-08 10:01:50'),
