  ('zcrm_5797994000002382486', 'LlamaIndex', 'LlamaIndex', 'Jordan Marquez', 'Jerry Lui', 'LlamaIndex enables enterprises to build AI Knowledge Assistants, improving data management, utilization, and enterprise intelligence. / Jerry Lui', 'HV STEM', 'SaaS', 'Spring 2025', NULL, 'Reached Out', 'Jordan Marquez', 'Rejected', NULL, NULL, NULL, '2025-03-05 07:45:37', '2025-05-08 10:01:25', '2025-05-08 10:01:25'),
  ('zcrm_5797994000002394049', 'Verse', 'Verse', 'Zeynep Acun', 'Matt Penfold', 'Verse provides software for organizations to understand, plan, and manage clean energy. Its SaaS platform, Aria™, leverages generative AI to help companies define clean energy goals and plan, procure, and manage optimal portfolios of clean energy assets at least cost. Customers can set parameters that target specific goals (e.g., cost, emissions,or hourly matching) and optimize for annual matching, emissions matching, or hourly matched carbon-free energy (CFE). By reducing transaction costs by up to 70% and providing real-time analysis within minutes, Aria helps scale and accelerate the clean energy transition.', 'HV Genesis', 'Sustainability', 'Spring 2025', NULL, 'Reached Out', 'Zeynep Acun', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', NULL, '2025-03-06 15:25:38', '2025-04-25 05:07:24', '2025-04-25 05:07:24'),
  ('zcrm_5797994000002394075', 'Avalanche Energy', 'Avalanche Energy', 'Zeynep Acun', 'Brian Riordan', 'Avalanche Energy is a fusion energy startup that develops micro-fusion reactors for distributed energy and mobility. The company''s modular reactor architecture can be stacked for limitless power applications and energy density, allowing it to offer clean energy while also decarbonizing the planet. It provides quick iterations of design, build,test, and fix cycles, allowing for speedier development and the rapid scaling required by the world.', 'HV Genesis', 'Sustainability', 'Spring 2025', NULL, 'Reached Out', 'Zeynep Acun', 'Rejected', 'Sustainability', 'Founder Communication (no response etc.)', NULL, '2025-03-06 15:32:02', '2025-04-25 05:08:51', '2025-04-25 05:08:51'),
